import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const _=JSON.parse('{"title":"审计与签名","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/audit.md","filePath":"modules/forge/audit.md","lastUpdated":null}'),r={name:"modules/forge/audit.md"};function i(c,t,l,u,s,n){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="审计与签名" tabindex="-1">审计与签名 <a class="header-anchor" href="#审计与签名" aria-label="Permalink to &quot;审计与签名&quot;">​</a></h1><p>Forge 在锻造成功后会向结果物品写入审计数据，用于追溯锻造来源和防篡改验证。</p><h2 id="审计数据" tabindex="-1">审计数据 <a class="header-anchor" href="#审计数据" aria-label="Permalink to &quot;审计数据&quot;">​</a></h2><p>锻造完成后，以下信息通过 <code>ForgeAuditBuilder</code> 写入物品 PDC：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>recipe_id</code></td><td>使用的配方 ID。</td></tr><tr><td><code>quality</code></td><td>品质等级名称。</td></tr><tr><td><code>multiplier</code></td><td>品质倍率。</td></tr><tr><td><code>forged_at</code></td><td>锻造时间戳。</td></tr><tr><td><code>materials_signature</code></td><td>材料贡献数据的稳定哈希签名。</td></tr><tr><td><code>output_item</code></td><td>输出物品来源简写。仅在配方配置了输出物品来源时写入。</td></tr><tr><td><code>materials</code></td><td>材料贡献列表。</td></tr></tbody></table><h2 id="材料签名" tabindex="-1">材料签名 <a class="header-anchor" href="#材料签名" aria-label="Permalink to &quot;材料签名&quot;">​</a></h2><p><code>materials_signature</code> 只对实际消耗数量大于 0 的材料贡献计算稳定哈希签名。相同的材料贡献组合总是得到相同签名，因此可以用于比对物品的锻造材料数据是否与预期一致。</p><h2 id="与刷新的关系" tabindex="-1">与刷新的关系 <a class="header-anchor" href="#与刷新的关系" aria-label="Permalink to &quot;与刷新的关系&quot;">​</a></h2><p>Forge 的物品刷新服务会读取审计数据中的 <code>recipe_id</code> 和 <code>quality</code>，据此重建锻造层展示。审计数据缺失或配方已被删除时，对应物品无法重建锻造层展示。</p><h2 id="用途场景" tabindex="-1">用途场景 <a class="header-anchor" href="#用途场景" aria-label="Permalink to &quot;用途场景&quot;">​</a></h2><ul><li>交易或回收系统可读取审计数据判断物品的配方来源与品质。</li><li>外部统计可按 <code>recipe_id</code>、<code>quality</code> 和 <code>forged_at</code> 聚合锻造产出。</li></ul><blockquote><p>Forge 未提供查看审计数据的内置命令。需要人工查看时，请使用支持读取物品 PDC 的外部工具。</p></blockquote>',12)])])}const p=e(r,[["render",i]]);export{_ as __pageData,p as default};
